<script setup lang="ts">
import { Bell,CheckCheck,RefreshCw,Send } from 'lucide-vue-next'
import type {Notice} from '~/types/models'
const {data:notices,error,refresh}=await useFetch<Notice[]>('/api/notifications', {key:'staff-notifications'})
const {dateTime}=useFormat();const onlyUnread=ref(false)
const filtered=computed(()=>notices.value?.filter(n=>!onlyUnread.value||!n.is_read)||[])
const unread=computed(()=>notices.value?.filter(n=>!n.is_read).length||0)
const visibleNotices=computed(()=>error?[]:filtered.value)
function noticeItemClass(n:Notice){return ['panel flex items-start gap-3 p-4',n.is_read?'':'bg-blue-50']}
const subject=ref('');const body=ref('');const busy=ref(false);const result=ref('')
async function sendAll(){result.value='';if(!subject.value.trim()||!body.value.trim()){result.value='Vui lòng nhập tiêu đề và nội dung.';return}busy.value=true;try{await $fetch('/api/notifications/broadcast',{method:'POST',body:{title:subject.value.trim(),body:body.value.trim()}});result.value='Đã gửi thông báo đến tất cả công dân.';subject.value='';body.value='';await refresh();await refreshNuxtData('staff-notifications-badge')}catch(e){result.value=readableError(e)}finally{busy.value=false}}
async function readAll(){if(busy.value||!unread.value)return;busy.value=true;try{await $fetch('/api/notifications/read-all',{method:'POST'});await refresh();await refreshNuxtData('staff-notifications-badge')}catch(e){result.value=readableError(e)}finally{busy.value=false}}
</script>
<template><div class="space-y-4"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="text-xl font-black">Thông báo &amp; công khai</h2><p class="text-sm text-muted">Gửi thông báo đến công dân và quản lý các thông báo hệ thống.</p></div></div><div class="grid gap-3 md:grid-cols-2"><section class="panel space-y-4 p-5"><h3 class="section-label"><Bell :size="20" class="text-blue-600"/>Gửi thông báo chung</h3><form class="space-y-3" @submit.prevent="sendAll"><div><label class="field-label">Tiêu đề</label><input v-model="subject" class="field" required minlength="3" maxlength="150" placeholder="Ví dụ: Thời gian xử lý hồ sơ adjustments"/></div><div><label class="field-label">Nội dung</label><textarea v-model="body" class="field" rows="4" required minlength="10" maxlength="2000" placeholder="Nội dung thông báo..."/></div><p v-if="result" class="rounded-lg bg-blue-50 p-3 text-sm text-brand-800">{{result}}</p><button class="btn-primary" :disabled="busy||!subject.trim()||!body.trim()" type="submit"><Send :size="16"/> Gửi đến tất cả công dân</button></form></section><section class="panel space-y-3 p-5"><h3 class="section-label"><CheckCheck :size="20" class="text-brand-600"/>Quản lý thông báo</h3><div class="flex gap-2"><button :class="['rounded-lg px-3 py-2 text-sm font-bold',!onlyUnread?'bg-blue-600 text-white':'bg-white text-slate-600']" @click="onlyUnread=false">Tất cả ({{notices?.length||0}})</button><button :class="['rounded-lg px-3 py-2 text-sm font-bold',onlyUnread?'bg-blue-600 text-white':'bg-white text-slate-600']" @click="onlyUnread=true">Chưa đọc ({{unread}})</button><button class="ml-auto btn-outline" :disabled="busy||!unread" @click="readAll"><CheckCheck :size="16"/> Đánh dấu tất cả đã đọc</button></div><div v-if="error" class="panel space-y-3 border-rose-200 p-5 text-rose-700">Không thể tải thông báo. <button class="btn-outline" @click="refresh()"><RefreshCw :size="16"/>Thử lại</button></div><div v-if="!error&amp;&amp;!filtered.length" class="panel p-7 text-center text-muted">Chưa có thông báo phù hợp.</div><div v-for="n in visibleNotices" :key="n.id" :class="noticeItemClass(n)"><span class="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-white text-brand-600"><Bell :size="22"/></span><div class="min-w-0 flex-1"><div class="flex flex-wrap items-start justify-between gap-2"><h3 class="text-sm font-extrabold">{{n.title}} <span v-if="!n.is_read" class="ml-1 rounded bg-blue-600 px-1.5 py-0.5 text-[10px] text-white">Mới</span></h3><small class="text-muted">{{dateTime(n.created_at)}}</small></div><p class="mt-1 text-sm leading-relaxed text-slate-600">{{n.body}}</p><div class="mt-3 flex flex-wrap gap-3"><NuxtLink v-if="n.application_id" :to="`/ho-so/${n.application_id}`" class="text-xs font-bold text-brand-700">Xem hồ sơ →</NuxtLink></div></div></div></section></div></div></template>
